#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn system_language() {
        assert_eq!(Lang::from_locales(["ru-RU"]), Lang::Ru);
        assert_eq!(Lang::from_locales(["ru_RU.UTF-8"]), Lang::Ru);
        assert_eq!(Lang::from_locales(["uk-UA", "ru-RU", "en-US"]), Lang::Ru);
        assert_eq!(Lang::from_locales(["de-CH"]), Lang::De);
        assert_eq!(Lang::from_locales(["es-419"]), Lang::Es);
        assert_eq!(Lang::from_locales(["fr"]), Lang::Fr);
        assert_eq!(Lang::from_locales(["it_IT@euro"]), Lang::It);
        assert_eq!(Lang::from_locales(["en-GB", "ru-RU"]), Lang::En);
        assert_eq!(Lang::from_locales(["ja-JP", "pt-BR"]), Lang::Pt);
        assert_eq!(Lang::from_locales(["pt_PT.UTF-8"]), Lang::Pt);
        assert_eq!(Lang::from_locales(["uz-Latn-UZ"]), Lang::Uz);
        assert_eq!(Lang::from_locales(["kk_KZ"]), Lang::Kk);
        assert_eq!(Lang::from_locales(["ja-JP"]), Lang::En);
        assert_eq!(Lang::from_locales(["C"]), Lang::En);
        assert_eq!(Lang::from_locales(Vec::<String>::new()), Lang::En);
    }

    /// Every character the interface shows — the translations in all languages and the
    /// string literals of the sources — has a glyph in the bundled fonts (no empty boxes).
    #[test]
    fn every_shown_character_has_a_glyph() {
        let sources = [
            include_str!("app.rs"),
            include_str!("assets.rs"),
            include_str!("analysis.rs"),
            include_str!("game_view.rs"),
            include_str!("library.rs"),
            include_str!("large_db.rs"),
            include_str!("board_search.rs"),
            include_str!("engine_offer.rs"),
            include_str!("notation.rs"),
            include_str!("review.rs"),
            include_str!("engines.rs"),
            include_str!("examples.rs"),
            include_str!("settings.rs"),
            include_str!("settings_ui.rs"),
            include_str!("widgets.rs"),
            include_str!("reference.rs"),
            include_str!("online.rs"),
            include_str!("online_ui.rs"),
            include_str!("update.rs"),
            include_str!("update_ui.rs"),
            include_str!("board.rs"),
            include_str!("engine_download.rs"),
            include_str!("main.rs"),
            include_str!("graphics.rs"),
            include_str!("translate.rs"),
            include_str!("translate_ui.rs"),
            include_str!("chatgpt.rs"),
            include_str!("san.rs"),
            include_str!("prep_ui.rs"),
        ];
        let mut chars = std::collections::BTreeSet::new();
        for row in ROWS {
            for text in row.iter() {
                chars.extend(text.chars());
            }
        }
        for src in sources {
            for line in src.lines().filter(|l| !l.trim_start().starts_with("//")) {
                // The parts of the line inside double quotes.
                for (i, part) in line.split('"').enumerate() {
                    if i % 2 == 1 {
                        chars.extend(part.chars());
                    }
                }
            }
        }
        // The characters each font of the text has (egui's own check cannot tell a
        // glyph of its last fallback from the replacement box).
        let fonts = crate::assets::font_definitions();
        let maps: Vec<std::collections::HashSet<u32>> = fonts.families
            [&egui::FontFamily::Proportional]
            .iter()
            .map(|name| {
                use skrifa::MetadataProvider as _;
                let data = &fonts.font_data[name];
                let font = skrifa::FontRef::new(&data.font).expect("a font");
                font.charmap().mappings().map(|(c, _)| c).collect()
            })
            .collect();
        let missing: Vec<String> = chars
            .into_iter()
            .filter(|c| !c.is_ascii() && !c.is_whitespace() && *c != '\u{fe0f}')
            .filter(|c| !maps.iter().any(|m| m.contains(&(*c as u32))))
            .map(|c| format!("{c} U+{:04X}", c as u32))
            .collect();
        assert!(missing.is_empty(), "no glyph for: {missing:?}");
    }

    /// Every `tr("…")` / `trf("…"` key used in the sources must have a translation row.
    #[test]
    fn all_used_keys_are_translated() {
        let sources = [
            include_str!("app.rs"),
            include_str!("assets.rs"),
            include_str!("analysis.rs"),
            include_str!("game_view.rs"),
            include_str!("library.rs"),
            include_str!("large_db.rs"),
            include_str!("board_search.rs"),
            include_str!("engine_offer.rs"),
            include_str!("notation.rs"),
            include_str!("review.rs"),
            include_str!("engines.rs"),
            include_str!("examples.rs"),
            include_str!("settings.rs"),
            include_str!("settings_ui.rs"),
            include_str!("widgets.rs"),
            include_str!("reference.rs"),
            include_str!("online.rs"),
            include_str!("online_ui.rs"),
            include_str!("update.rs"),
            include_str!("update_ui.rs"),
            include_str!("board.rs"),
            include_str!("engine_download.rs"),
            include_str!("main.rs"),
            include_str!("graphics.rs"),
            include_str!("translate.rs"),
            include_str!("translate_ui.rs"),
            include_str!("chatgpt.rs"),
            include_str!("san.rs"),
            include_str!("prep_ui.rs"),
        ];
        let mut missing = Vec::new();
        let mut found = 0;
        for src in sources {
            for marker in ["tr(", "trf("] {
                for (i, _) in src.match_indices(marker) {
                    // Skip identifiers that merely end in `tr` (e.g. `str(`).
                    let prev = src[..i].chars().next_back();
                    if prev.is_some_and(|c| c.is_alphanumeric() || c == '_') {
                        continue;
                    }
                    // rustfmt may move the literal to the next line.
                    let rest = src[i + marker.len()..].trim_start();
                    let Some(rest) = rest.strip_prefix('"') else {
                        continue;
                    };
                    let Some(end) = rest.find('"') else { continue };
                    found += 1;
                    let key = &rest[..end];
                    if !table().contains_key(key) {
                        missing.push(key.to_string());
                    }
                }
            }
        }
        assert!(found > 100, "scanner found only {found} keys");
        assert!(missing.is_empty(), "untranslated keys: {missing:?}");
    }

    /// Rodent's styles are shown through `tr` of their fields, out of the scanner's sight.
    #[test]
    fn every_style_is_translated() {
        for st in crate::play::STYLES {
            for key in [st.title(), st.about] {
                assert!(
                    ROWS.iter().any(|row| row[0] == key),
                    "untranslated style text: {key}"
                );
            }
        }
    }

    #[test]
    fn rows_are_unique_and_complete() {
        let mut seen = std::collections::HashSet::new();
        for row in ROWS {
            assert!(seen.insert(row[0]), "duplicate key {}", row[0]);
            assert!(
                row.iter().all(|s| !s.is_empty()),
                "empty cell in {}",
                row[0]
            );
        }
    }
}
